    /** Every candidate of every set. */
    public static final List<Design> ALL = List.of(SERVANTS, EMBERDACTYL, CINDER_MOBS).stream().flatMap(List::stream).toList();

    /** The candidate with this number (the first one if there's none). */
    public static Design byNumber(int number)
    {
        for (Design design : ALL)
        {
            if (design.number() == number)
            {
                return design;
            }
        }
        return ALL.get(0);
    }

    private FireDesigns() {}
